#include <HBEngine/SceneRender.hpp>
#include <nlohmann/json.hpp>
#include <fstream>
#include <iostream>
using namespace hb::gpu;using Json=nlohmann::json;
static int display(float v){v=std::clamp(v,0.f,1.f);return int(std::round(255*(v<=.0031308f?v*12.92f:1.055f*std::pow(v,1/2.4f)-.055f)));}
static ProbeSettings settings(const Json& row){ProbeSettings p;const auto& s=row.at("settings");p.center=s.at("center").get<std::array<float,4>>();p.minimum=s.at("minimum").get<std::array<float,4>>();p.maximum=s.at("maximum").get<std::array<float,4>>();p.options=s.at("options").get<std::array<float,4>>();p.localX=s.at("localX").get<std::array<float,4>>();p.localY=s.at("localY").get<std::array<float,4>>();p.localZ=s.at("localZ").get<std::array<float,4>>();p.faceScale=s.at("faceScale").get<std::array<float,4>>();p.projectionMinimum=s.at("projectionMinimum").get<std::array<float,4>>();p.projectionMaximum=s.at("projectionMaximum").get<std::array<float,4>>();p.projectionX=s.at("projectionX").get<std::array<float,4>>();p.projectionY=s.at("projectionY").get<std::array<float,4>>();p.projectionZ=s.at("projectionZ").get<std::array<float,4>>();return p;}
int main(int argc,char** argv){try{
 if(argc!=2){throw std::runtime_error("fixture path");}std::ifstream input(argv[1]);const auto cases=Json::parse(input);Device gpu;SceneRenderer r(gpu,8,8);SceneFrame frame;frame.eye={0,0,10,1};frame.ambient={0,0,0,1};r.setLights({});r.begin(frame);auto capture=r.createProbe(16);for(UINT face=0;face<6;face++){r.beginProbe(capture,face,identity,{0,0,0,1},{.3f,.5f,.7f,1});r.endProbe();}r.filterProbe(capture);
 auto mesh=r.createMesh({{{-1,-1,.5f}},{{1,-1,.5f}},{{1,1,.5f}},{{-1,1,.5f}}},{0,1,2,0,2,3});SceneMaterial material;material.unlit=true;material.toneMapped=false;const std::string declarations="StructuredBuffer<float> queryValues:register(t7);",query="float3 queryAt=float3(queryValues[0],queryValues[1],queryValues[2]),queryRay=float3(queryValues[3],queryValues[4],queryValues[5]);";auto directProgram=r.createProgram(declarations,query+"base.rgb=hbBuiltinNormalUnit(probeDirection(probeSettings[0],queryAt,queryRay),float3(0,0,0))*.5+.5;base.a=probeWeight(probeSettings[0],queryAt);",{0,0,0,0,0,1}),atlasProgram=r.createProgram(declarations,query+"AtlasProbe chosen=hbAtlasProbe(0);base.rgb=hbBuiltinNormalUnit(probeDirection(chosen.settings,queryAt,queryRay),float3(0,0,0))*.5+.5;base.a=probeWeight(chosen.settings,queryAt);",{0,0,0,0,0,1});
 const auto draw=[&](bool atlas,const std::array<SceneRenderer::ProbeBinding,2>& direct){r.begin(frame);r.draw(mesh,identity,identity,material,{},{},0,0,atlas?&atlasProgram:&directProgram,{},{},nullptr,nullptr,nullptr,atlas?nullptr:&direct,nullptr,0,nullptr,atlas);return r.readPixels();};int samples=0,maxError=0;std::vector<SceneRenderer::ProbeBinding> bindings(3);for(auto& binding:bindings)binding.resource=&capture;
 for(const auto& row:cases){const auto p=settings(row);const auto point=row.at("point").get<std::vector<float>>(),ray=row.at("ray").get<std::vector<float>>();auto values=point;values.insert(values.end(),ray.begin(),ray.end());r.setProgramParameters(directProgram,values);r.setProgramParameters(atlasProgram,values);std::array<SceneRenderer::ProbeBinding,2> direct{};direct[0]={&capture,p};bindings[0].settings=p;for(unsigned i=1;i<3;i++){bindings[i].settings=p;bindings[i].settings.center[3]=0;}r.setGlobalProbes(bindings);auto expected=row.at("expected").get<std::array<double,4>>();const double length=std::hypot(expected[0],expected[1],expected[2]);for(unsigned c=0;c<3;c++)expected[c]=length?expected[c]/length:0;for(bool atlas:{false,true}){const auto pixels=draw(atlas,direct);for(unsigned c=0;c<4;c++){const int actual=pixels[(4*8+4)*4+c],reference=c==3?int(std::round(std::clamp(expected[c],0.,1.)*255)):display(float(expected[c]*.5+.5)),error=std::abs(actual-reference);maxError=std::max(maxError,error);if(error>3)throw std::runtime_error(Json({{"sample",samples},{"atlas",atlas},{"channel",c},{"actual",actual},{"reference",reference},{"row",row}}).dump());}samples++;}}
 const auto copies=r.probeAtlasCopies(),layouts=r.probeAtlasLayoutBuilds(),tree=r.probeAtlasSpatialBuilds(),bytes=r.probeAtlasMetadataBytes(),updates=r.probeAtlasMetadataFastUpdates();bindings[0].settings.projectionMinimum[3]=bindings[0].settings.projectionMinimum[3]==3?0:3;r.setGlobalProbes(bindings);if(r.probeAtlasCopies()!=copies||r.probeAtlasLayoutBuilds()!=layouts||r.probeAtlasSpatialBuilds()!=tree||r.probeAtlasMetadataBytes()!=bytes+320||r.probeAtlasMetadataFastUpdates()!=updates+1)throw std::runtime_error("Projection metadata must retain captures/layout/spatial and update one320B record");auto invalid=bindings;invalid[0].settings.projectionMinimum[3]=4;bool rejected=false;try{r.setGlobalProbes(invalid);}catch(const std::runtime_error&){rejected=true;}if(!rejected||r.probeAtlasMetadataBytes()!=bytes+320)throw std::runtime_error("Invalid projection changed committed metadata");r.setGlobalProbes({});r.releaseProbes();if(r.probeAtlasCPUBytes()||r.probeAtlasBytes())throw std::runtime_error("Projection atlas retained after release");std::cout<<Json({{"passed",true},{"samples",samples},{"maxErrorBytes",maxError},{"directSettingsBytes",sizeof(ProbeSettings)},{"atlasRecordBytes",sizeof(ProbeSettings)+16},{"metadataOnly",true},{"invalidAtomic",true},{"released",true},{"scope","Actual D3D11 raster material debug programs read production direct304B bindings and atlas320B records, normalized projection/weight compared to independent geometry oracle; actual HDR capture, metadata-only320B edit/no image/layout/tree rebuild, invalid atomic rejection and release. Physical material shading assessed in browser manager and real packaged game separately."}}).dump();return 0;
}catch(const std::exception& error){std::cerr<<error.what();return 1;}}
